const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET is not configured');
const timestamp = String($json.headers?.['x-gtm-timestamp'] || '');
const signature = String($json.headers?.['x-gtm-signature'] || '');
const sentAt = Number(timestamp);
if (!Number.isInteger(sentAt) || Math.abs(Math.floor(Date.now() / 1000) - sentAt) > 300) throw new Error('Rejected stale webhook');
const body = JSON.stringify($json.body);
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
const valid = signature.length === expected.length && crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
if (!valid) throw new Error('Rejected invalid webhook signature');
return [{ json: $json.body }];

const action = $json;
if (action.action_type !== 'create_or_update_crm_lead') throw new Error('invalid_crm_action');
const payload = action.payload || {};
for (const field of ['lead_id', 'name', 'email', 'company', 'classification']) {
  if (!String(payload[field] || '').trim()) throw new Error('invalid_crm_payload');
}
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(payload.email))) throw new Error('invalid_crm_email');
const properties = {
  email: String(payload.email),
  gtm_agentos_lead_id: String(payload.lead_id),
  firstname: String(payload.name),
  company: String(payload.company),
  jobtitle: String(payload.job_title || '')
};
return [{ json: { ...action, provider_request: { inputs: [{ id: String(payload.email), idProperty: 'email', properties }] } } }];

const action = $('Prepare HubSpot Upsert').item.json;
const reference = $json.results?.[0]?.id || $json.id;
if (!reference) throw new Error('hubspot_contact_reference_missing');
return [{ json: { ...action, external_reference: String(reference).slice(0, 500), provider: 'hubspot' } }];

const action = $json;
if (action.action_type !== 'send_approved_email') throw new Error('invalid_email_action');
const payload = action.payload || {};
const configuredRecipient = String($env.EMAIL_TEST_RECIPIENT || '').trim().toLowerCase();
const requestedRecipient = String(payload.to_email || '').trim().toLowerCase();
if (!configuredRecipient) throw new Error('email_validation_recipient_not_configured');
if (!requestedRecipient || requestedRecipient !== configuredRecipient) throw new Error('email_recipient_not_allowed');
if (!String(payload.body || '').trim()) throw new Error('invalid_email_payload');
const controlledBody = 'TESTE CONTROLADO DO GTM AGENTOS — nenhuma ação é necessária.\n\n' + String(payload.body);
return [{ json: { ...action, provider_idempotency_key: String(action.idempotency_key), provider_request: { from: 'GTM AgentOS <onboarding@resend.dev>', to: [requestedRecipient], subject: 'GTM AgentOS — End-to-End Test', text: controlledBody } } }];

const action = $('Prepare Resend Email').item.json;
const reference = $json.id;
if (!reference) throw new Error('resend_email_reference_missing');
return [{ json: { ...action, external_reference: String(reference).slice(0, 500), provider: 'resend' } }];

const crypto = require('crypto');
const { URL } = require('url');
const secret = $env.N8N_WEBHOOK_SECRET;
const callbackUrl = $env.GTM_AGENTOS_CALLBACK_URL;
if (!secret || !callbackUrl) throw new Error('Callback environment is not configured');
const parsedUrl = new URL(callbackUrl);
const localHosts = new Set(['localhost', '127.0.0.1', '::1']);
if (parsedUrl.protocol !== 'https:' && !localHosts.has(parsedUrl.hostname)) throw new Error('Callback URL must use HTTPS');
if (parsedUrl.username || parsedUrl.password || parsedUrl.search || parsedUrl.hash) throw new Error('Callback URL cannot contain credentials, query, or fragment');
const placeholderReferences = { create_follow_up_task: 'placeholder-task', draft_outreach_email: 'placeholder-draft', mark_lead_status: 'placeholder-status' };
const externalReference = String($json.external_reference || placeholderReferences[$json.action_type] || '').slice(0, 500);
if (!externalReference) throw new Error('provider_reference_missing');
const callback = { action_id: $json.action_id, status: 'completed', external_reference: externalReference, metadata: { workflow: 'gtm-agentos-actions', provider: String($json.provider || 'placeholder') } };
const rawBody = JSON.stringify(callback);
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + rawBody).digest('hex');
return [{ json: { callbackUrl, rawBody, timestamp, signature, action_id: $json.action_id } }];
